using UnityEngine;
using Verse;

namespace LivingLandscapes.Geology;

/// <summary>
/// A cliff band or steps on the higher side of a height change, made of a particular rock (granite, marble...).
/// Its look depends on which of its 8 neighbours are lower (<see cref="LowerNeighbours"/>, bits as in
/// <see cref="CliffPlan.Lower"/>): one texture per pattern, generated by Source/ArtTools/generate_cliff_art.py: the rim of
/// a rock wall along every drop (a dark foot, fissured rock, a lit lip) with the ground showing through in the middle,
/// rounded so it meets its neighbours seamlessly, tinted with the rock's colour. Soft shadows fall on the lower cells to
/// the south, east and west. Steps (no longer generated; kept for old saves) look like the band.
/// </summary>
public class Building_Cliff : Building
{
    private const string ArtPath = "Things/Building/LivingLandscapes/Cliff/";
    private const int South = 4, East = 2, West = 8;

    private static Material shadowSouth, shadowEast, shadowWest;

    private ThingDef rock;
    private byte lowerNeighbours;

    /// <summary>The natural rock this cliff is made of. Set before spawning.</summary>
    public ThingDef Rock
    {
        get => rock;
        set => rock = value;
    }

    /// <summary>Which neighbours are lower ground (8 bits). Set before spawning.</summary>
    public byte LowerNeighbours
    {
        get => lowerNeighbours;
        set => lowerNeighbours = value;
    }

    public override Color DrawColor
    {
        get => rock?.graphicData?.color ?? base.DrawColor;
        set => base.DrawColor = value;
    }

    public override string LabelNoCount => rock == null ? base.LabelNoCount : $"{rock.label} {def.label}";

    public override void Print(SectionLayer layer)
    {
        int mask = lowerNeighbours != 0 ? lowerNeighbours : 1 << Rotation.AsInt;
        string name = "Cliff_" + mask.ToString("000");
        Vector3 center = Position.ToVector3Shifted();
        center.y = def.Altitude;
        Printer_Plane.PrintPlane(layer, center, Vector2.one, MaterialPool.MatFrom(ArtPath + name, ShaderDatabase.Cutout, DrawColor));

        shadowSouth ??= MaterialPool.MatFrom(ArtPath + "Shadow_South", ShaderDatabase.Transparent, Color.white);
        shadowEast ??= MaterialPool.MatFrom(ArtPath + "Shadow_East", ShaderDatabase.Transparent, Color.white);
        shadowWest ??= MaterialPool.MatFrom(ArtPath + "Shadow_West", ShaderDatabase.Transparent, Color.white);
        float shadowAltitude = AltitudeLayer.Shadows.AltitudeFor();
        if ((mask & South) != 0)
            PrintShadow(layer, IntVec3.South, shadowSouth, shadowAltitude);
        if ((mask & East) != 0)
            PrintShadow(layer, IntVec3.East, shadowEast, shadowAltitude);
        if ((mask & West) != 0)
            PrintShadow(layer, IntVec3.West, shadowWest, shadowAltitude);
    }

    private void PrintShadow(SectionLayer layer, IntVec3 direction, Material mat, float altitude)
    {
        IntVec3 cell = Position + direction;
        if (!cell.InBounds(Map))
            return;
        Vector3 center = cell.ToVector3Shifted();
        center.y = altitude;
        Printer_Plane.PrintPlane(layer, center, Vector2.one, mat);
    }

    public override void ExposeData()
    {
        base.ExposeData();
        Scribe_Defs.Look(ref rock, "rock");
        Scribe_Values.Look(ref lowerNeighbours, "lowerNeighbours");
    }
}
